import * as T from 'three';import{EffectComposer}from'three/addons/postprocessing/EffectComposer.js';import{RenderPass}from'three/addons/postprocessing/RenderPass.js';import{UnrealBloomPass}from'three/addons/postprocessing/UnrealBloomPass.js';import{OutputPass}from'three/addons/postprocessing/OutputPass.js';export class GraphicsEngine{constructor(){this.scene=new T.Scene();this.scene.background=new T.Color(0x9ddff3);this.scene.fog=new T.Fog(0x9ddff3,65,160);this.renderer=new T.WebGLRenderer({canvas:document.querySelector('#world'),antialias:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<1000?1.25:1.5));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=.9;this.camera=new T.PerspectiveCamera(55,innerWidth/innerHeight,.1,250);this.scene.add(new T.HemisphereLight(0xd7f7ff,0x86ad98,1.45));const sun=new T.DirectionalLight(0xfff1d9,2.2);sun.position.set(20,35,15);sun.castShadow=true;sun.shadow.mapSize.set(innerWidth<1000?1024:2048,innerWidth<1000?1024:2048);Object.assign(sun.shadow.camera,{left:-60,right:60,top:60,bottom:-60,far:130});sun.shadow.normalBias=.04;this.scene.add(sun);this.composer=new EffectComposer(this.renderer);this.composer.addPass(new RenderPass(this.scene,this.camera));this.bloom=new UnrealBloomPass(new T.Vector2(innerWidth,innerHeight),.23,.3,1);this.composer.addPass(this.bloom);this.composer.addPass(new OutputPass());this.clouds=[];for(let i=0;i<18;i++){const g=new T.Group();for(let j=0;j<4;j++){const m=new T.Mesh(new T.IcosahedronGeometry(2+j*.2,1),new T.MeshStandardMaterial({color:0xffffff,flatShading:true}));m.position.set(j*2,Math.sin(j)*.7,0);g.add(m)}g.position.set((i%6-3)*23,23+i%3*4,Math.floor(i/6)*35-40);this.scene.add(g);this.clouds.push(g)}addEventListener('resize',()=>this.resize());this.resize()}resize(){this.camera.aspect=innerWidth/innerHeight;this.camera.updateProjectionMatrix();this.renderer.setSize(innerWidth,innerHeight);this.composer.setSize(innerWidth,innerHeight)}render(t,calm){this.bloom.strength=calm?.08:.25;this.clouds.forEach((c,i)=>c.position.x+=Math.sin(i)*.001);this.composer.render()}}
